NEO4J.ActorWithMovies.loadAll.where:
MATCH (n:Actor)
WHERE (n.name = $name) AND EXISTS { MATCH (n)-[:ACTED_IN]->(:Movie) }
RETURN {root: {props: properties(n), labels: labels(n)}, rels: {movies: [(n)-[r1:ACTED_IN]->(t1:Movie) | {props: properties(t1), labels: labels(t1)}]}} AS result

NEO4J.ActorWithMovies.count:
MATCH (n:Actor)
WHERE EXISTS { MATCH (n)-[:ACTED_IN]->(:Movie) }
RETURN count(n) AS count

NEO4J.ActorWithDirectors.loadAll:
MATCH (n:Actor)
WHERE EXISTS { MATCH (n)-[:ACTED_IN]->(:Movie)-[:DIRECTED_BY]->(:Person:Director) }
RETURN {root: {props: properties(n), labels: labels(n)}, rels: {directors: [x1 IN reduce(acc = [], y IN [(n)-[:ACTED_IN]->(:Movie)-[:DIRECTED_BY]->(t1:Person:Director) | t1] | CASE WHEN y IN acc THEN acc ELSE acc + y END) | {props: properties(x1), labels: labels(x1)}]}} AS result

NEO4J.ActorWithLatestMovie.loadAll:
MATCH (n:Actor)
WHERE EXISTS { MATCH (n)-[:ACTED_IN]->(:Movie) }
RETURN {root: {props: properties(n), labels: labels(n)}, rels: {movie: head([(n)-[r1:ACTED_IN]->(t1:Movie) | {props: properties(t1), labels: labels(t1)}])}} AS result

NEO4J.query.PersonCareer.across:
MATCH (n:Person)
WHERE EXISTS { MATCH (n)-[_r1:WORKS_FOR]->(_x0:Organization) WHERE _x0.name = $_q0 } AND n.bio CONTAINS $_q1 AND EXISTS { MATCH (n)-[_r3:WORKS_FOR]->(_x2:Organization) WHERE _r3.role = $_q2 }
RETURN {root: {props: properties(n), labels: labels(n)}, rels: {employmentHistory: [(n)-[r1:WORKS_FOR]->(t1:Organization) | {rel: properties(r1), target: {props: properties(t1), labels: labels(t1)}}]}} AS result

NEO4J.query.LocationAncestors.deep:
MATCH (n:Location)
WHERE EXISTS { MATCH (n)<-[:HAS_LOCATION*1..5]-(_x0:Location) WHERE _x0.name = $_q0 }
RETURN {root: {props: properties(n), labels: labels(n)}, rels: {within: [x1 IN reduce(acc = [], y IN [(n)<-[:HAS_LOCATION*1..5]-(t1:Location) | t1] | CASE WHEN y IN acc THEN acc ELSE acc + y END) | {props: properties(x1), labels: labels(x1)}]}} AS result

