    IF v_ok THEN
        OPEN c FOR SELECT JSON_OBJECT('found' VALUE CASE WHEN v_made THEN NULL ELSE v_found END, 'now' VALUE (SELECT stamp FROM drivine_node WHERE nid = v_root), 'related' VALUE JSON('[]') RETURNING CLOB) AS "result:json" FROM dual;
