    v_roots SYS.ODCINUMBERLIST;
    v_targets SYS.ODCINUMBERLIST := SYS.ODCINUMBERLIST();
    v_deleted NUMBER;
    c SYS_REFCURSOR;
BEGIN
    SELECT n.nid BULK COLLECT INTO v_roots FROM drivine_node n
WHERE JSON_EXISTS(n.labels, '$?(@ == "Location")') AND ((JSON_EXISTS(n.props, '$?(@."uuid" == $id__)' PASSING $id AS "id__")));
    NULL;
    DELETE FROM drivine_node WHERE nid IN (SELECT column_value FROM TABLE(v_roots));
    v_deleted := SQL%ROWCOUNT;
    DELETE FROM drivine_node x WHERE x.nid IN (SELECT column_value FROM TABLE(v_targets));
    OPEN c FOR SELECT v_deleted AS "deleted" FROM dual;
    DBMS_SQL.RETURN_RESULT(c);
END;

ORACLE.saveAll.fragments:
DECLARE
    v_offered VARCHAR2(40) := $x_stamp;
    v_root NUMBER;
    v_found VARCHAR2(40);
    v_made BOOLEAN := FALSE;
    v_ok BOOLEAN := TRUE;
    c SYS_REFCURSOR;
    v_before0 CLOB;
    v_after0 CLOB;
    v_before1 CLOB;
    v_after1 CLOB;

    FUNCTION two_tokens(s VARCHAR2) RETURN BOOLEAN IS
    BEGIN
        RETURN s IS NOT NULL AND LENGTH(s) = 33 AND SUBSTR(s, 17, 1) = ':';
    END;

    PROCEDURE restamp(p NUMBER, p_changed BOOLEAN) IS
        s VARCHAR2(40);
    BEGIN
        SELECT stamp INTO s FROM drivine_node WHERE nid = p;
        IF p_changed OR NOT two_tokens(s) THEN
            IF two_tokens(s) THEN s := SUBSTR(v_offered, 1, 16) || SUBSTR(s, 17);
            ELSE s := v_offered; END IF;
            UPDATE drivine_node SET stamp = s WHERE nid = p;
        END IF;
    END;

    PROCEDURE relink(p NUMBER) IS
        s VARCHAR2(40);
    BEGIN
        SELECT stamp INTO s FROM drivine_node WHERE nid = p;
        IF two_tokens(s) THEN s := SUBSTR(s, 1, 17) || SUBSTR(v_offered, 18);
        ELSE s := v_offered; END IF;
        UPDATE drivine_node SET stamp = s WHERE nid = p;
    END;

    FUNCTION find_node(p_match VARCHAR2, p_id VARCHAR2) RETURN NUMBER IS
        ids SYS.ODCINUMBERLIST;
    BEGIN
        EXECUTE IMMEDIATE 'SELECT nid FROM drivine_node n WHERE ' || p_match BULK COLLECT INTO ids USING p_id;
        IF ids.COUNT > 1 THEN
            RAISE_APPLICATION_ERROR(-20001, ids.COUNT || ' nodes have the id ' || p_id || '. An id is one node''s.');
        END IF;
        RETURN CASE WHEN ids.COUNT = 1 THEN ids(1) END;
    END;

    FUNCTION make_node(p_labels VARCHAR2) RETURN NUMBER IS
        v NUMBER;
    BEGIN
        INSERT INTO drivine_node (labels, props) VALUES (JSON(p_labels), JSON('{}')) RETURNING nid INTO v;
        RETURN v;
    END;

    FUNCTION has(a JSON_ARRAY_T, s VARCHAR2) RETURN BOOLEAN IS
    BEGIN
        FOR i IN 0 .. a.get_size - 1 LOOP
            IF a.get_string(i) = s THEN RETURN TRUE; END IF;
        END LOOP;
        RETURN FALSE;
    END;

    -- Merges the patch into the node's properties, adds and removes labels, and records an open label field's labels.
    -- Whether any of it changed the node.
    FUNCTION apply_node(p NUMBER, p_props VARCHAR2, p_add VARCHAR2, p_remove VARCHAR2, p_record VARCHAR2, p_replace BOOLEAN)
        RETURN BOOLEAN IS
        old_props JSON;
        new_props JSON;
        old_labels JSON;
        labels JSON_ARRAY_T;
        kept JSON_ARRAY_T := JSON_ARRAY_T();
        additions JSON_ARRAY_T := JSON_ARRAY_T.parse(p_add);
        removals JSON_ARRAY_T := JSON_ARRAY_T.parse(p_remove);
        props JSON_OBJECT_T;
        recorded JSON_ARRAY_T;
        same NUMBER;
        relabelled BOOLEAN := FALSE;
        kept_text VARCHAR2(4000);
    BEGIN
        SELECT props, labels INTO old_props, old_labels FROM drivine_node WHERE nid = p FOR UPDATE;
        SELECT JSON_MERGEPATCH(old_props, JSON(p_props)) INTO new_props FROM dual;
        labels := JSON_ARRAY_T.parse(JSON_SERIALIZE(old_labels));
        FOR i IN 0 .. labels.get_size - 1 LOOP
            IF has(removals, labels.get_string(i)) THEN relabelled := TRUE; ELSE kept.append(labels.get_string(i)); END IF;
        END LOOP;
        FOR i IN 0 .. additions.get_size - 1 LOOP
            IF NOT has(kept, additions.get_string(i)) THEN kept.append(additions.get_string(i)); relabelled := TRUE; END IF;
        END LOOP;
        IF p_record IS NOT NULL THEN
            props := JSON_OBJECT_T.parse(JSON_SERIALIZE(new_props));
            IF p_replace OR NOT props.has(p_record) THEN recorded := JSON_ARRAY_T();
            ELSE recorded := props.get_array(p_record); END IF;
            FOR i IN 0 .. additions.get_size - 1 LOOP
                IF NOT has(recorded, additions.get_string(i)) THEN recorded.append(additions.get_string(i)); END IF;
            END LOOP;
            props.put(p_record, recorded);
            new_props := JSON(props.to_string());
        END IF;
        SELECT CASE WHEN JSON_EQUAL(old_props, new_props) THEN 1 ELSE 0 END INTO same FROM dual;
        -- An object type's methods are PL/SQL's: called in SQL, they are refused (ORA-40573).
        kept_text := kept.to_string();
        UPDATE drivine_node SET props = new_props, labels = JSON(kept_text) WHERE nid = p;
        RETURN same = 0 OR relabelled;
    END;

    FUNCTION write_node(p_match VARCHAR2, p_id VARCHAR2, p_labels VARCHAR2, p_props VARCHAR2, p_add VARCHAR2,
        p_remove VARCHAR2, p_record VARCHAR2, p_replace BOOLEAN) RETURN NUMBER IS
        v NUMBER := find_node(p_match, p_id);
        made BOOLEAN := v IS NULL;
    BEGIN
        IF made THEN v := make_node(p_labels); END IF;
        restamp(v, apply_node(v, p_props, p_add, p_remove, p_record, p_replace) OR made);
        RETURN v;
    END;

    -- Joins two nodes by a relationship of the type, unless one is there (in either direction, for BOTH), and merges
    -- its properties. Both ends are marked when one is made or its properties change.
    PROCEDURE link(p_from NUMBER, p_to NUMBER, p_type VARCHAR2, p_dir VARCHAR2, p_props VARCHAR2) IS
        e NUMBER;
        old_props JSON;
        new_props JSON;
        same NUMBER;
    BEGIN
        BEGIN
            SELECT eid, props INTO e, old_props FROM drivine_edge
            WHERE type = p_type AND ((p_dir IN ('OUT', 'BOTH') AND src = p_from AND dst = p_to)
                OR (p_dir IN ('IN', 'BOTH') AND src = p_to AND dst = p_from))
            FETCH FIRST 1 ROW ONLY;
        EXCEPTION WHEN NO_DATA_FOUND THEN e := NULL;
        END;
        IF e IS NULL THEN
            INSERT INTO drivine_edge (src, dst, type, props) VALUES (CASE WHEN p_dir = 'IN' THEN p_to ELSE p_from END,
                CASE WHEN p_dir = 'IN' THEN p_from ELSE p_to END, p_type, JSON(NVL(p_props, '{}')));
            relink(p_from);
            relink(p_to);
        ELSIF p_props IS NOT NULL THEN
            SELECT JSON_MERGEPATCH(old_props, JSON(p_props)) INTO new_props FROM dual;
            SELECT CASE WHEN JSON_EQUAL(old_props, new_props) THEN 1 ELSE 0 END INTO same FROM dual;
            IF same = 0 THEN
                UPDATE drivine_edge SET props = new_props WHERE eid = e;
                relink(p_from);
                relink(p_to);
            END IF;
        END IF;
    END;

    -- Removes the relationships p_dropped selects from the root, marks both ends, and deletes each removed node
    -- p_unreferenced counts as no longer referred to.
    PROCEDURE trim_edges(p_root NUMBER, p_dropped VARCHAR2, p_keep VARCHAR2, p_unreferenced VARCHAR2, p_held VARCHAR2) IS
        eids SYS.ODCINUMBERLIST;
        nids SYS.ODCINUMBERLIST;
        unreferenced NUMBER;
    BEGIN
        EXECUTE IMMEDIATE p_dropped BULK COLLECT INTO eids, nids USING p_root, p_keep;
        FOR i IN 1 .. eids.COUNT LOOP
            DELETE FROM drivine_edge WHERE eid = eids(i);
        END LOOP;
        FOR i IN 1 .. nids.COUNT LOOP
            relink(nids(i));
        END LOOP;
        IF eids.COUNT > 0 THEN relink(p_root); END IF;
        IF p_unreferenced IS NOT NULL THEN
            FOR i IN 1 .. nids.COUNT LOOP
                IF nids(i) <> p_root THEN
                    EXECUTE IMMEDIATE p_unreferenced INTO unreferenced USING nids(i), p_held;
                    IF unreferenced > 0 THEN DELETE FROM drivine_node WHERE nid = nids(i); END IF;
                END IF;
            END LOOP;
        END IF;
    END;
BEGIN
    SELECT NVL(JSON_ARRAYAGG(JSON_OBJECT('id' VALUE JSON_QUERY(n.props, '$."uuid"'), 'stamp' VALUE NVL(n.stamp, '-')) RETURNING CLOB), '[]') INTO v_before0 FROM drivine_node n WHERE JSON_EXISTS(n.labels, '$?(@ == "Person")') AND EXISTS (SELECT 1 FROM JSON_TABLE($x_1, '$[*]' COLUMNS (v JSON PATH '$')) t WHERE JSON_EXISTS(n.props, '$?(@."uuid" == $v)' PASSING t.v AS "v"));
    SELECT NVL(JSON_ARRAYAGG(JSON_OBJECT('id' VALUE JSON_QUERY(n.props, '$."uuid"'), 'stamp' VALUE NVL(n.stamp, '-')) RETURNING CLOB), '[]') INTO v_before1 FROM drivine_node n WHERE JSON_EXISTS(n.labels, '$?(@ == "Organization")') AND EXISTS (SELECT 1 FROM JSON_TABLE($x_2, '$[*]' COLUMNS (v JSON PATH '$')) t WHERE JSON_EXISTS(n.props, '$?(@."uuid" == $v)' PASSING t.v AS "v"));
    v_root := write_node($x_3, $x_4, $x_5, $x_6, '[]', '[]', NULL, FALSE);
    v_root := write_node($x_7, $x_8, $x_9, $x_10, '[]', '[]', NULL, FALSE);
    v_root := write_node($x_11, $x_12, $x_13, $x_14, '[]', '[]', NULL, FALSE);
    SELECT NVL(JSON_ARRAYAGG(JSON_OBJECT('id' VALUE JSON_QUERY(n.props, '$."uuid"'), 'stamp' VALUE NVL(n.stamp, '-')) RETURNING CLOB), '[]') INTO v_after0 FROM drivine_node n WHERE JSON_EXISTS(n.labels, '$?(@ == "Person")') AND EXISTS (SELECT 1 FROM JSON_TABLE($x_15, '$[*]' COLUMNS (v JSON PATH '$')) t WHERE JSON_EXISTS(n.props, '$?(@."uuid" == $v)' PASSING t.v AS "v"));
    SELECT NVL(JSON_ARRAYAGG(JSON_OBJECT('id' VALUE JSON_QUERY(n.props, '$."uuid"'), 'stamp' VALUE NVL(n.stamp, '-')) RETURNING CLOB), '[]') INTO v_after1 FROM drivine_node n WHERE JSON_EXISTS(n.labels, '$?(@ == "Organization")') AND EXISTS (SELECT 1 FROM JSON_TABLE($x_16, '$[*]' COLUMNS (v JSON PATH '$')) t WHERE JSON_EXISTS(n.props, '$?(@."uuid" == $v)' PASSING t.v AS "v"));
    OPEN c FOR SELECT JSON_OBJECT('groups' VALUE JSON_ARRAY(JSON_OBJECT('before' VALUE JSON(v_before0), 'after' VALUE JSON(v_after0) RETURNING JSON), JSON_OBJECT('before' VALUE JSON(v_before1), 'after' VALUE JSON(v_after1) RETURNING JSON) RETURNING JSON) RETURNING CLOB) AS "result:json" FROM dual;
    DBMS_SQL.RETURN_RESULT(c);
END;

