        END LOOP;
        FOR i IN 1 .. nids.COUNT LOOP
            relink(nids(i));
        END LOOP;
        IF eids.COUNT > 0 THEN relink(p_root); END IF;
        IF p_unreferenced IS NOT NULL THEN
            FOR i IN 1 .. nids.COUNT LOOP
                IF nids(i) <> p_root THEN
                    EXECUTE IMMEDIATE p_unreferenced INTO unreferenced USING nids(i), p_held;
                    IF unreferenced > 0 THEN DELETE FROM drivine_node WHERE nid = nids(i); END IF;
                END IF;
            END LOOP;
        END IF;
    END;
BEGIN
    SELECT JSON_SERIALIZE(JSON_SCALAR($id)) INTO v_id FROM dual;
    v_root := find_node($x_match, v_id);
    IF v_root IS NOT NULL THEN
        SELECT stamp INTO v_found FROM drivine_node WHERE nid = v_root FOR UPDATE;
        v_meets := 1;
        IF v_meets > 0 THEN
            SELECT JSON_SERIALIZE(JSON_MERGEPATCH(JSON($set), JSON(NVL($vectors, '{}')))) INTO v_patch FROM dual;
            v_changed := apply_node(v_root, v_patch, '[]', '[]', NULL, FALSE);
            restamp(v_root, v_changed);
