        UNION ALL SELECT x4.nid FROM drivine_node n CROSS JOIN drivine_edge e1 JOIN drivine_node x2 ON x2.nid = e1.dst CROSS JOIN drivine_edge e3 JOIN drivine_node x4 ON x4.nid = e3.dst WHERE n.nid IN (SELECT column_value FROM TABLE(v_roots)) AND e1.src = n.nid AND e1.type = 'HAS_LOCATION' AND JSON_EXISTS(x2.labels, '$?(@ == "Location")') AND e3.src = x2.nid AND e3.type = 'HAS_LOCATION' AND JSON_EXISTS(x4.labels, '$?(@ == "Location")')
        UNION ALL SELECT x6.nid FROM drivine_node n CROSS JOIN drivine_edge e1 JOIN drivine_node x2 ON x2.nid = e1.dst CROSS JOIN drivine_edge e3 JOIN drivine_node x4 ON x4.nid = e3.dst CROSS JOIN drivine_edge e5 JOIN drivine_node x6 ON x6.nid = e5.dst WHERE n.nid IN (SELECT column_value FROM TABLE(v_roots)) AND e1.src = n.nid AND e1.type = 'HAS_LOCATION' AND JSON_EXISTS(x2.labels, '$?(@ == "Location")') AND e3.src = x2.nid AND e3.type = 'HAS_LOCATION' AND JSON_EXISTS(x4.labels, '$?(@ == "Location")') AND e5.src = x4.nid AND e5.type = 'HAS_LOCATION' AND JSON_EXISTS(x6.labels, '$?(@ == "Location")')) t WHERE t.nid NOT IN (SELECT column_value FROM TABLE(v_roots))),
    cascade_all AS (SELECT column_value AS nid FROM TABLE(v_roots) UNION SELECT nid FROM cascade_targets),
    cascade_kept (nid) AS (
    SELECT t.nid FROM cascade_targets t WHERE EXISTS (SELECT 1 FROM drivine_edge e WHERE (e.src = t.nid AND e.dst NOT IN (SELECT nid FROM cascade_all)) OR (e.dst = t.nid AND e.src NOT IN (SELECT nid FROM cascade_all)))
    UNION ALL
    SELECT CASE WHEN e.src = k.nid THEN e.dst ELSE e.src END FROM cascade_kept k JOIN drivine_edge e ON (e.type = 'HAS_LOCATION' AND e.src = k.nid) WHERE CASE WHEN e.src = k.nid THEN e.dst ELSE e.src END IN (SELECT nid FROM cascade_targets)
    ) CYCLE nid SET looped TO 'Y' DEFAULT 'N'
    SELECT nid BULK COLLECT INTO v_targets FROM cascade_targets WHERE nid NOT IN (SELECT nid FROM cascade_kept);
    DELETE FROM drivine_node WHERE nid IN (SELECT column_value FROM TABLE(v_roots));
    v_deleted := SQL%ROWCOUNT;
    DELETE FROM drivine_node x WHERE x.nid IN (SELECT column_value FROM TABLE(v_targets));
    OPEN c FOR SELECT v_deleted AS "deleted" FROM dual;
    DBMS_SQL.RETURN_RESULT(c);
END;

