    EXECUTE IMMEDIATE 'INSERT INTO drivine_t_Articletitle_b5000eae (nid, doc) SELECT n.nid, JSON_OBJECT(''title'' VALUE JSON_VALUE(n.props, ''$."title"'' RETURNING CLOB) ABSENT ON NULL RETURNING JSON) FROM drivine_node n WHERE JSON_EXISTS(n.labels, ''$?(@ == "Article")'') AND NOT EXISTS (SELECT 1 FROM drivine_t_Articletitle_b5000eae s WHERE s.nid = n.nid)';
    BEGIN
        MERGE INTO drivine_schema c
        USING (SELECT 'FULLTEXT_INDEX' AS kind, 'Article' AS label, '["title"]' AS properties FROM dual) k
        ON (c.kind = k.kind AND c.label = k.label AND c.properties = k.properties)
        WHEN NOT MATCHED THEN INSERT (kind, label, properties, name, object_name, details)
            VALUES (k.kind, k.label, k.properties, 'Article_title_fulltext', 'drivine_t_Articletitle_b5000eae', '{}');
    EXCEPTION
        WHEN DUP_VAL_ON_INDEX THEN NULL;
    END;
END;

